// ── Utility Functions ─────────────────────────────────────────────────

export function getWBMLAByConstituency(acNo: number): LegislatorProfile | undefined {
  return WB_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getWBMLAByName(name: string): LegislatorProfile | undefined {
  const q = name.toLowerCase();
  return WB_MLA_PROFILES.find(p =>
    p.name.toLowerCase().includes(q) || p.displayName?.toLowerCase().includes(q)
  );
}

export function getWBMLAsByParty(party: string): LegislatorProfile[] {
  return WB_MLA_PROFILES.filter(p => p.currentParty === party);
}

export function getWBFemaleMLAs(): LegislatorProfile[] {
  return WB_MLA_PROFILES.filter(p => p.gender === 'F');
}

export function getWBCrorepatiMLAs(): LegislatorProfile[] {
  return WB_MLA_PROFILES.filter(p =>
    p.financialHistory.some(f => f.isCrorepati)
  );
}

export function getWBMLAsWithCriminalCases(): LegislatorProfile[] {
  return WB_MLA_PROFILES.filter(p => p.criminalRecord.hasCriminalCases);
}

export function getWBMultiTermMLAs(): LegislatorProfile[] {
  return WB_MLA_PROFILES.filter(p => p.termsServed >= 2);
}

export function getWBPartyStrength(): Record<string, number> {
  const strength: Record<string, number> = {};
  for (const p of WB_MLA_PROFILES) {
    strength[p.currentParty] = (strength[p.currentParty] || 0) + 1;
  }
  return strength;
}

export function getWBWealthStats() {
  const sorted = [...WB_MLA_PROFILES]
    .filter(p => p.financialHistory[0]?.totalAssets > 0)
    .sort((a, b) => (b.financialHistory[0]?.totalAssets || 0) - (a.financialHistory[0]?.totalAssets || 0));
  return {
    richest: sorted[0],
    poorest: sorted[sorted.length - 1],
    totalMLAs: sorted.length,
    crorepatis: sorted.filter(p => p.financialHistory[0]?.isCrorepati).length,
    avgNetWorth: sorted.reduce((s, p) => s + (p.financialHistory[0]?.netWorth || 0), 0) / sorted.length,
  };
}

export function getWBMLAProfile(acNo: number): LegislatorProfile | undefined {
  return getWBMLAByConstituency(acNo);
}
export function getAllWBMLAs(): LegislatorProfile[] {
  return WB_MLA_PROFILES;
}
